<?php
declare(strict_types=1);
require_once __DIR__.'/Database.php';
require_once __DIR__.'/Auth.php';
require_once __DIR__.'/AppNavigation.php';
require_once __DIR__.'/WorkspaceUI.php';
require_once __DIR__.'/FamilyPickupService.php';

final class FamilyPickupExperience {
    public static function handles(string $route):bool {return in_array($route,['/student-profile/family','/student-profile/family/review'],true);}
    public static function render(string $route,string $basePath):never {
        Auth::startSession();$db=Database::connect(dirname(__DIR__));$viewer=Auth::currentUser($db);
        if(!$viewer)self::go($basePath.'/login');
        if($route==='/student-profile/family/review'){
            if(!AccessPolicy::canManagePeople($viewer)){http_response_code(403);exit('Staff authorization required.');}
            $_SESSION['family_pickup_csrf']??=bin2hex(random_bytes(24));
            if($_SERVER['REQUEST_METHOD']==='POST'){
                if(!hash_equals((string)$_SESSION['family_pickup_csrf'],(string)($_POST['csrf_token']??''))){http_response_code(403);exit('Invalid session token.');}
                try{
                    $student=(int)($_POST['student_id']??0);$id=(int)($_POST['request_id']??0);
                    FamilyPickupService::decide($db,$viewer,$student,$id,($_POST['action']??'')==='request_approve');
                    $_SESSION['family_review_flash']=['success','Relationship request reviewed.'];
                }catch(RuntimeException|PDOException $e){$_SESSION['family_review_flash']=['error',$e instanceof PDOException?'The review could not be saved.':$e->getMessage()];}
                self::go($basePath.'/student-profile/family/review');
            }
            self::reviewPage($db,$viewer,$basePath);
        }
        $student=(int)($_POST['student_id']??$_GET['student']??0);
        try { $canManage=FamilyPickupService::canManage($db,$viewer,$student); }
        catch (PDOException $error) { self::unavailable($basePath,$viewer); }
        if(!$canManage){http_response_code(404);exit('Student family settings unavailable.');}
        $_SESSION['family_pickup_csrf']??=bin2hex(random_bytes(24));
        if($_SERVER['REQUEST_METHOD']==='POST'){
            if(!hash_equals((string)$_SESSION['family_pickup_csrf'],(string)($_POST['csrf_token']??''))){http_response_code(403);exit('Invalid session token.');}
            try{
                $action=(string)($_POST['action']??'');
                if($action==='pickup_save')FamilyPickupService::savePickup($db,$viewer,$student,$_POST);
                elseif($action==='pickup_status')FamilyPickupService::togglePickup($db,$viewer,$student,(int)($_POST['pickup_id']??0),($_POST['active']??'')==='1');
                elseif($action==='adult_request')FamilyPickupService::requestAdult($db,$viewer,$student,$_POST);
                elseif($action==='request_cancel')FamilyPickupService::cancelRequest($db,$viewer,$student,(int)($_POST['request_id']??0));
                elseif($action==='adult_pickup')FamilyPickupService::setAdultPickup($db,$viewer,$student,(int)($_POST['relationship_id']??0),($_POST['active']??'')==='1');
                elseif($action==='adult_remove')FamilyPickupService::deactivateAdult($db,$viewer,$student,(int)($_POST['relationship_id']??0));
                elseif($action==='request_approve')FamilyPickupService::decide($db,$viewer,$student,(int)($_POST['request_id']??0),true);
                elseif($action==='request_reject')FamilyPickupService::decide($db,$viewer,$student,(int)($_POST['request_id']??0),false);
                else throw new RuntimeException('Unknown family management action.');
                $_SESSION['family_pickup_flash']=['success','Changes saved.'];
            }catch(RuntimeException|PDOException $e){$_SESSION['family_pickup_flash']=['error',$e instanceof PDOException?'Unable to save. Check that the family/pickup migration has been applied.':$e->getMessage()];}
            self::go($basePath.'/student-profile/family?student='.$student);
        }
        $profile=StudentProfileService::profile($db,$student);
        $adults=FamilyPickupService::adults($db,$student);
        $pickup=FamilyPickupService::pickup($db,$student);
        $requests=FamilyPickupService::requests($db,$student);$pickupByAdult=[];foreach($pickup as $person)if(!empty($person['linked_guardian_user_id']))$pickupByAdult[(int)$person['linked_guardian_user_id']]=(bool)$person['active'];
        $staff=AccessPolicy::canManagePeople($viewer);
        $flash=$_SESSION['family_pickup_flash']??null;unset($_SESSION['family_pickup_flash']);
        $e=static fn(mixed $v):string=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$url=static fn(string $p):string=>($basePath?:'').$p;
        $hidden='<input type="hidden" name="csrf_token" value="'.$e($_SESSION['family_pickup_csrf']).'"><input type="hidden" name="student_id" value="'.$student.'">';
        header('Content-Type: text/html; charset=utf-8');?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Family & pickup · CTSMD Connect</title>
<link rel="stylesheet" href="<?=$url('/assets/css/app.css')?>"><link rel="stylesheet" href="<?=$url('/assets/css/unified-navigation.css')?>">
<style>
.fp-wrap{max-width:1050px;margin:0 auto;padding:25px 22px 70px}.fp-back{display:inline-block;margin-bottom:14px;color:#a6192e;font-weight:750}.fp-hero{margin-bottom:22px}.fp-hero small{font-size:11px;font-weight:800;color:#a6192e;letter-spacing:.1em}.fp-hero h1{margin:5px 0;font:700 30px Georgia,serif;color:#292127}.fp-hero p{color:#6b6066;max-width:700px;font-size:14px}.fp-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.fp-card{background:#fff;border:1px solid #e4dce0;border-radius:15px;padding:20px;min-width:0}.fp-card h2{margin:0 0 5px;font:700 22px Georgia,serif}.fp-card>p{color:#625b60;font-size:13px;line-height:1.5}.fp-entry{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 0;border-top:1px solid #eee7ea}.fp-entry strong{display:block;font-size:14px}.fp-entry small{display:block;color:#72676e;font-size:12px;margin-top:2px}.fp-entry form{display:inline-block;margin:0}.fp-entry button{border:1px solid #d7c9cf;border-radius:8px;padding:7px 10px;background:#fff;color:#843046;cursor:pointer;font-weight:700;font-size:12px}.fp-card details{border-top:1px solid #eee7ea;margin-top:14px;padding-top:15px}.fp-card summary{color:#a6192e;font-weight:800;cursor:pointer}.fp-form{display:grid;gap:12px;margin-top:15px}.fp-form label{display:grid;gap:5px;color:#35282e;font-size:13px;font-weight:700}.fp-form input:not([type=checkbox]),.fp-form select,.fp-form textarea{width:100%;min-width:0;box-sizing:border-box;border:1px solid #d8cbd0;border-radius:9px;background:#fff;padding:10px;font:inherit;color:#292127}.fp-form label.fp-check{display:flex;align-items:center;gap:9px}.fp-form button{background:#a6192e;border:0;border-radius:10px;padding:12px 16px;color:#fff;font-weight:800;cursor:pointer}.fp-alert{padding:12px 16px;margin-bottom:16px;border-radius:9px;background:#fff3f3;border:1px solid #ecccd1;color:#772639}.fp-alert.success{background:#eff9f1;border-color:#c8e4d0;color:#28613f}.fp-tag{font-size:11px;font-weight:750;color:#77666e}.fp-muted{opacity:.65}.fp-tip{font-size:12px;color:#71666d}.fp-full{grid-column:1/-1}@media(max-width:760px){.fp-grid{grid-template-columns:1fr}.fp-wrap{padding:16px 12px 60px}.fp-card{padding:16px}}
</style><?php WorkspaceUI::styles($basePath); ?></head><body class="app-body ux-workspace ux-operational ux-family-settings"><a class="ux-skip" href="#ux-main">Skip to main content</a><div class="unified-shell"><?php AppNavigation::renderSidebar('/student-profile',$basePath,$viewer);?><main class="unified-main" id="ux-main" tabindex="-1"><?php AppNavigation::renderHeader('Family','Family & pickup',$basePath,[]);?><div class="fp-wrap">
<a class="fp-back" href="<?=$url('/student-profile?student='.$student)?>">← Student profile</a>
<header class="fp-hero"><small>CHILD-SPECIFIC SETTINGS</small><h1><?=$e($profile['legal_name'])?></h1><p>Manage this child's connected adults and authorized pickup people. Changes here never automatically carry over to siblings.</p></header>
<?php if($flash):?><div class="fp-alert <?=$e($flash[0])?>" role="status"><?=$e($flash[1])?></div><?php endif;?>
<?php if($staff):?><p><a href="<?=$url('/student-profile/family/review')?>" style="color:#a6192e;font-weight:800">Review all pending family requests →</a></p><?php endif;?><div class="fp-grid">
<section class="fp-card"><h2>Parents & caregivers</h2><p>Connected adults can have their own CTSMD accounts. New access requests require staff approval.</p>
<?php foreach($adults as $person):?><div class="fp-entry <?=$person['status']==='active'?'':'fp-muted'?>"><div><strong><?=$e($person['name'])?></strong><small><?=$e(ucfirst($person['relationship_type']))?><?=$person['is_primary']?' · Primary':''?> · <?=$e(ucfirst($person['status']))?></small></div>
<?php if($person['status']==='active'):?><div><form method="post"><?=$hidden?><input type="hidden" name="action" value="adult_pickup"><input type="hidden" name="relationship_id" value="<?=(int)$person['id']?>"><input type="hidden" name="active" value="<?=!empty($pickupByAdult[(int)$person['guardian_user_id']])?'0':'1'?>"><button type="submit"><?=!empty($pickupByAdult[(int)$person['guardian_user_id']])?'Pickup ✓':'Allow pickup'?></button></form> <?php if($staff):?><form method="post" onsubmit="return confirm('Remove this adult’s access to this child?');"><?=$hidden?><input type="hidden" name="action" value="adult_remove"><input type="hidden" name="relationship_id" value="<?=(int)$person['id']?>"><button type="submit">Remove</button></form><?php endif;?></div><?php endif;?></div><?php endforeach;?>
<details><summary>Add parent or caregiver</summary><form method="post" class="fp-form"><?=$hidden?><input type="hidden" name="action" value="adult_request"><label>Adult's email<input type="email" name="adult_email" maxlength="190" required placeholder="adult@example.com"></label><label>Relationship<input type="text" name="relationship_label" maxlength="100" required placeholder="Mother, father, stepfather, grandparent…"></label><label>Account access<select name="relationship_type"><option value="parent">Parent</option><option value="guardian">Legal guardian</option><option value="caregiver">Caregiver</option></select></label><details style="padding:12px;border:1px solid #d9cdd2;border-radius:10px"><summary style="cursor:pointer;font-weight:700">ⓘ Parent, Guardian, or Caregiver?</summary><p class="fp-tip"><b>Parent:</b> Parent-level family and child-information access.</p><p class="fp-tip"><b>Guardian:</b> Legally authorized adult with parent-level access.</p><p class="fp-tip"><b>Caregiver:</b> Limited scheduling and transportation access, not casting, forms, or private conversations. Account approvals are currently restricted.</p><p class="fp-tip"><b>Pickup is separate:</b> Authorize this person for this child below; change it later at any time. Pickup-only people need no account.</p></details><label class="fp-check"><input type="checkbox" name="pickup_authorized" value="1" checked> Authorized for pickup?</label><p class="fp-tip">The request stays pending until CTSMD staff verifies and approves it. Adults need an active account for account access. Caregiver access is not enabled until restricted permissions are available; pickup-only contacts work today.</p><button type="submit">Request connection</button></form></details>
</section>
<section class="fp-card"><h2>Authorized pickup people</h2><p>These people may collect this child, but do not receive CTSMD account access. No account is required.</p>
<?php foreach($pickup as $person):?><div class="fp-entry <?=$person['active']?'':'fp-muted'?>"><div><strong><?=$e($person['name'])?></strong><small><?=$e($person['relationship_label'])?><?=$person['phone']?' · '.$e($person['phone']):''?><?=$person['active']?'':' · Inactive'?></small></div><div>
<form method="post"><?=$hidden?><input type="hidden" name="action" value="pickup_status"><input type="hidden" name="pickup_id" value="<?=(int)$person['id']?>"><input type="hidden" name="active" value="<?=$person['active']?'0':'1'?>"><button type="submit"><?=$person['active']?'Remove':'Restore'?></button></form>
<?php if(!$person['linked_guardian_user_id']):?><details><summary>Edit</summary><form class="fp-form" method="post"><?=$hidden?><input type="hidden" name="action" value="pickup_save"><input type="hidden" name="pickup_id" value="<?=(int)$person['id']?>"><label>Name<input name="name" required maxlength="190" value="<?=$e($person['name'])?>"></label><label>Relationship<input name="relationship_label" required maxlength="100" value="<?=$e($person['relationship_label'])?>"></label><label>Phone<input name="phone" maxlength="60" value="<?=$e($person['phone'])?>"></label><label>Notes<textarea name="notes" maxlength="500"><?=$e($person['notes'])?></textarea></label><button type="submit">Save person</button></form></details><?php endif;?>
</div></div><?php endforeach;?>
<details><summary>Add pickup-only person</summary><form method="post" class="fp-form"><?=$hidden?><input type="hidden" name="action" value="pickup_save"><label>Full name<input name="name" maxlength="190" required></label><label>Relationship<input name="relationship_label" maxlength="100" placeholder="Grandmother, family friend…" required></label><label>Phone (optional)<input name="phone" maxlength="60" type="tel"></label><label>Notes (optional)<textarea name="notes" maxlength="500"></textarea></label><button type="submit">Add pickup person</button></form></details>
</section>
<section class="fp-card fp-full"><h2>Relationship requests</h2><p>New adults cannot see the child's private information until an authorized staff member reviews the request.</p>
<?php if(!$requests):?><p class="fp-tip">No requests yet.</p><?php endif;?>
<?php foreach($requests as $request):?><div class="fp-entry"><div><strong><?=$e($request['adult_email'])?></strong><small><?=$e($request['relationship_label'])?> · <?=$e(ucfirst($request['status']))?><?=$request['pickup_authorized']?' · Pickup requested':''?></small></div><?php if($request['status']==='pending'):?><form method="post"><?=$hidden?><input type="hidden" name="action" value="request_cancel"><input type="hidden" name="request_id" value="<?=(int)$request['id']?>"><button type="submit">Cancel request</button></form><?php endif;?><?php if($staff&&$request['status']==='pending'):?><div><form method="post"><?=$hidden?><input type="hidden" name="action" value="request_approve"><input type="hidden" name="request_id" value="<?=(int)$request['id']?>"><button type="submit">Approve</button></form> <form method="post"><?=$hidden?><input type="hidden" name="action" value="request_reject"><input type="hidden" name="request_id" value="<?=(int)$request['id']?>"><button type="submit">Reject</button></form></div><?php endif;?></div><?php endforeach;?>
</section></div></div></main></div><script src="<?=$url('/assets/js/unified-navigation.js')?>"></script></body></html><?php exit;
    }
    private static function unavailable(string $basePath,array $viewer):never {
        http_response_code(503);
        $u=static fn(string $path):string=>htmlspecialchars(($basePath?:'').$path,ENT_QUOTES,'UTF-8');
        header('Content-Type: text/html; charset=utf-8'); ?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Family settings unavailable · CTSMD Connect</title><link rel="stylesheet" href="<?=$u('/assets/css/app.css')?>"><link rel="stylesheet" href="<?=$u('/assets/css/unified-navigation.css')?>"><?php WorkspaceUI::styles($basePath); ?></head><body class="app-body ux-workspace ux-operational ux-family-settings"><a class="ux-skip" href="#ux-main">Skip to main content</a><div class="unified-shell"><?php AppNavigation::renderSidebar('/student-profile',$basePath,$viewer);?><main class="unified-main" id="ux-main" tabindex="-1"><?php AppNavigation::renderHeader('Family','Family & pickup',$basePath,[]);?><div class="fp-wrap"><section class="fp-card" role="alert"><h2>Family settings are unavailable</h2><p>CTSMD could not load this record. No relationship or pickup change has been made. Please contact CTSMD staff if this continues.</p><a href="<?=$u('/family-hub')?>">Return to your household</a></section></div></main></div><script src="<?=$u('/assets/js/unified-navigation.js')?>"></script></body></html><?php exit;
    }
    private static function reviewPage(PDO $db,array $viewer,string $basePath):never {
        $rows=FamilyPickupService::pendingForStaff($db);
        $flash=$_SESSION['family_review_flash']??null;unset($_SESSION['family_review_flash']);
        $esc=static fn(mixed $s):string=>htmlspecialchars((string)$s,ENT_QUOTES,'UTF-8');
        $url=static fn(string $path):string=>($basePath?:'').$path;
        header('Content-Type: text/html; charset=utf-8');?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Family relationship requests · CTSMD Connect</title><link rel="stylesheet" href="<?=$url('/assets/css/app.css')?>"><link rel="stylesheet" href="<?=$url('/assets/css/unified-navigation.css')?>"><style>.fr-wrap{max-width:850px;margin:0 auto;padding:24px}.fr-wrap h1{font-family:Georgia,serif}.fr-card{background:#fff;border:1px solid #e5dbe0;border-radius:12px;padding:16px;margin:12px 0}.fr-card small{display:block;color:#6c6268;margin:5px 0}.fr-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.fr-actions form{margin:0}.fr-actions button{padding:9px 14px;border:1px solid #ad2541;background:#a6192e;color:#fff;border-radius:8px;cursor:pointer}.fr-actions button.secondary{background:#fff;color:#a6192e}.fr-alert{padding:12px;background:#fff2e5;border-radius:9px}</style><?php WorkspaceUI::styles($basePath); ?></head><body class="app-body ux-workspace ux-operational ux-family-settings"><a class="ux-skip" href="#ux-main">Skip to main content</a><div class="unified-shell"><?php AppNavigation::renderSidebar('/student-profile',$basePath,$viewer);?><main class="unified-main" id="ux-main" tabindex="-1"><?php AppNavigation::renderHeader('People','Family requests',$basePath,[]);?><div class="fr-wrap"><h1>Family relationship requests</h1><p>Verify the adult's authority and any safeguarding restrictions before granting child account access. Pickup-only people do not need account access.</p><?php if($flash):?><div class="fr-alert" role="status"><?=$esc($flash[1])?></div><?php endif;?><?php if(!$rows):?><div class="fr-card">No pending family requests.</div><?php endif;?>
<?php foreach($rows as $row):?><article class="fr-card"><strong><?=$esc($row['student_name'])?> · <?=$esc($row['relationship_label'])?></strong><small>Adult: <?=$esc($row['adult_email'])?> · Requested by <?=$esc($row['requested_by_name'])?></small><small>Requested access: <?=$esc(ucfirst($row['relationship_type']))?> · Pickup: <?=$row['pickup_authorized']?'Yes':'No'?> · <?=$esc($row['created_at'])?></small><div class="fr-actions"><a href="<?=$url('/student-profile/family?student='.(int)$row['student_user_id'])?>">Review child profile</a><form method="post"><input type="hidden" name="csrf_token" value="<?=$esc($_SESSION['family_pickup_csrf'])?>"><input type="hidden" name="student_id" value="<?=(int)$row['student_user_id']?>"><input type="hidden" name="request_id" value="<?=(int)$row['id']?>"><button name="action" value="request_approve" type="submit">Approve</button></form><form method="post"><input type="hidden" name="csrf_token" value="<?=$esc($_SESSION['family_pickup_csrf'])?>"><input type="hidden" name="student_id" value="<?=(int)$row['student_user_id']?>"><input type="hidden" name="request_id" value="<?=(int)$row['id']?>"><button class="secondary" name="action" value="request_reject" type="submit">Reject</button></form></div></article><?php endforeach;?></div></main></div><script src="<?=$url('/assets/js/unified-navigation.js')?>"></script></body></html><?php exit;
